// The Core Report's census data: every downtown core and its region in each
// census year sdsc-data has pulled (2001 and 2021 today).
//
// coreSeries.csv and coreAreas.csv are generated by `npm run core-series` from
// sdsc-data's downtown_vs_cma_comparison.csv and boundary files. Re-run it
// whenever sdsc-data publishes new outputs; new census years flow through.

import { csvParse } from 'd3';
import { CORE_CITIES } from '../lib/data/coredata/coreCities.js';
// Imported as raw text and parsed here: a third the size of the row objects
// the CSV plugin would otherwise inline.
import areasRaw from '../lib/data/coredata/coreAreas.csv?raw';
import raw from '../lib/data/coredata/coreSeries.csv?raw';

const THEME_LABELS = {
	overall_growth: 'Growth',
	migration_and_imm: 'Migration',
	housing_supply: 'Housing',
	Demographics: 'People & work'
};

// R writes missing values as "NA"; suppressed or absent values stay missing
// rather than reading as zero.
function num(text) {
	if (text == null || text === '' || text === 'NA') return null;
	const value = Number(text);
	return Number.isFinite(value) ? value : null;
}

const slug = (text) =>
	String(text ?? '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-|-$/g, '');

/** Key for one census variable within a profile: `indicator|variable_name`. */
export const variableKey = (indicator, variable) => `${indicator}|${variable}`;

const rows = csvParse(raw);

/** Census years present in the data, oldest first. */
export const CENSUS_YEARS = rows.columns
	.map((column) => Number(column.match(/^value_(\d{4})_dt$/)?.[1]))
	.filter(Boolean)
	.sort((a, b) => a - b);

export const LATEST_YEAR = CENSUS_YEARS.at(-1);

function emptyProfiles() {
	return Object.fromEntries(CENSUS_YEARS.map((year) => [year, {}]));
}

/**
 * One entry per downtown. `downtown` and `cma` each hold a profile per census
 * year, and a profile maps `variableKey(indicator, variable)` to
 * `{ value, percent }`: the count (or average, for income) and its share of
 * the indicator's total, 0-100, where the pipeline computed one.
 */
export const CITIES = CORE_CITIES.map((city) => ({
	...city,
	downtown: emptyProfiles(),
	cma: emptyProfiles()
}));

const cityByKey = new Map(CITIES.map((city) => [city.key, city]));

for (const row of rows) {
	const city = cityByKey.get(row.city);
	if (!city) continue;
	const key = variableKey(row.indicator, row.variable_name);
	for (const year of CENSUS_YEARS) {
		for (const [geo, suffix] of [
			['downtown', 'dt'],
			['cma', 'cma']
		]) {
			city[geo][year][key] = {
				value: num(row[`value_${year}_${suffix}`]),
				percent: num(row[`percent_${year}_${suffix}`])
			};
		}
	}
}

// Population density, people per km², added to each profile under
// `variableKey('Density', 'Population density')`. Downtown boundaries don't
// change between censuses, so a downtown's area serves every year. CMA land
// areas are Statistics Canada's for one boundary year only (CMAs are redrawn
// each census), so regions have no density in other years.
const POPULATION = variableKey('Population', 'Population');
const DENSITY = variableKey('Density', 'Population density');

function setDensity(profile, area) {
	const population = profile[POPULATION]?.value;
	profile[DENSITY] = {
		value: population != null && area ? population / area : null,
		percent: null
	};
}

for (const row of csvParse(areasRaw)) {
	const city = cityByKey.get(row.city);
	if (!city) continue;
	const cmaYear = Number(row.cma_year);
	for (const year of CENSUS_YEARS) {
		setDensity(city.downtown[year], num(row.downtown_km2));
		setDensity(city.cma[year], year === cmaYear ? num(row.cma_km2) : null);
	}
}

/**
 * Every census variable, grouped theme → indicator → variable, for the
 * "change" module's pickers. "Total …" rows are denominators and are left out.
 * Shares are plotted wherever the pipeline computed one, because they compare
 * fairly as populations grow; other variables fall back to the raw value.
 */
export const THEMES = (() => {
	const themes = new Map();
	for (const row of rows) {
		if (row.city !== CITIES[0].key) continue; // every city carries the same variables
		if (!row.variable_name || /^total\b/i.test(row.variable_name)) continue;

		if (!themes.has(row.theme)) {
			themes.set(row.theme, {
				key: slug(row.theme),
				label: THEME_LABELS[row.theme] ?? row.theme,
				indicators: new Map()
			});
		}
		const indicators = themes.get(row.theme).indicators;
		if (!indicators.has(row.indicator)) {
			indicators.set(row.indicator, {
				key: `${slug(row.theme)}--${slug(row.indicator)}`,
				label: row.indicator,
				variables: []
			});
		}
		indicators
			.get(row.indicator)
			.variables.push(describeVariable(row.indicator, row.variable_name));
	}

	return [...themes.values()].map((theme) => ({
		...theme,
		indicators: [...theme.indicators.values()]
	}));
})();

function describeVariable(indicator, name) {
	const key = variableKey(indicator, name);
	const hasShare = CITIES.some((city) =>
		CENSUS_YEARS.some((year) => city.downtown[year][key]?.percent != null)
	);
	const field = hasShare ? 'percent' : 'value';
	const isIncome = /average/i.test(name) && /income/i.test(name);

	// "Household Size: 1 person" reads as "1 person" under its indicator.
	const prefix = `${indicator}: `;
	return {
		key: `${slug(indicator)}--${slug(name)}`,
		label: name.startsWith(prefix) ? name.slice(prefix.length) : name,
		title: name,
		indicator,
		get: (profile) => profile?.[key]?.[field] ?? null,
		format: hasShare ? 'pct' : isIncome ? 'money' : 'int',
		// Raw counts run from a few thousand downtown residents to millions in a
		// region, so they need a log axis; shares and incomes don't.
		scale: hasShare || isIncome ? 'lin' : 'log',
		zeroFloor: hasShare,
		nominalDollars: isIncome
	};
}

/** Census years in which at least one downtown has a value for `get`. */
export function yearsWithData(get) {
	return CENSUS_YEARS.filter((year) => CITIES.some((city) => get(city.downtown[year]) != null));
}
